"use client";

import { useCallback, useState } from "react";
import { useTranslation } from "react-i18next";
import { Button } from "@/modules/ui/components/button";

interface DownloadMyDataProps {
  userId: string;
}

export const DownloadMyData = ({ userId }: Readonly<DownloadMyDataProps>) => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(false);

  const handleDownload = useCallback(async () => {
    setLoading(true);
    try {
      const response = await fetch(`/api/users/${userId}/download-my-data`, {
        method: "POST",
      });
      if (!response.ok) {
        throw new Error("Failed to download data");
      }
      const blob = await response.blob();
      if (typeof window !== "undefined" && typeof document !== "undefined") {
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = "formbricks-data.json";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(link.href);
      }
    } catch (error) {
      console.error("Error downloading data:", error);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  return (
    <Button variant="secondary" size="sm" onClick={handleDownload} disabled={loading}>
      {loading ? t("common.downloading") : t("workspace.settings.profile.download_my_data")}
    </Button>
  );
};

import { NextResponse } from "next/server";
import { prisma } from "@formbricks/database";
import { AuthenticationError, AuthorizationError } from "@formbricks/types/errors";
import { getSession } from "@/modules/auth/lib/session";

export async function POST(
  _request: Request,
  { params }: { params: Promise<{ userId: string }> }
) {
  const session = await getSession();
  if (!session?.user) {
    return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  }

  const { userId } = await params;
  if (session.user.id !== userId) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: {
      name: true,
      email: true,
      locale: true,
      notificationSettings: true,
    },
  });

  if (!user) {
    throw new AuthorizationError("User not found");
  }

  const memberships = await prisma.membership.findMany({
    where: { userId: session.user.id },
    select: {
      organization: {
        select: {
          name: true,
        },
      },
      role: true,
    },
  });

  const organizations = memberships.map((m) => ({
    name: m.organization.name,
    role: m.role,
  }));

  const data = {
    name: user.name,
    email: user.email,
    locale: user.locale,
    notificationSettings: user.notificationSettings,
    organizations,
  };

  const json = JSON.stringify(data, null, 2);
  const blob = new Blob([json], { type: "application/json" });

  return new NextResponse(blob, {
    headers: {
      "Content-Type": "application/json",
      "Content-Disposition": 'attachment; filename="formbricks-data.json"',
    },
  });
}

import { AuthenticationError } from "@formbricks/types/errors";
import { AccountActivity } from "@/app/(app)/account/settings/profile/components/AccountActivity";
