import { UpgradePrompt } from "@/modules/ui/components/upgrade-prompt";

const Page = async () => {
  const isTwoFactorAuthEnabled = await getIsTwoFactorAuthEnabled();
  const isMultiOrgEnabled = await getIsMultiOrgEnabled();
  const t = await getTranslate();
  const session = await getSession();
  if (!session?.user) {
    throw new AuthenticationError(t("common.not_authenticated"));
  }

  const organizationsWithSingleOwner = await getOrganizationsWhereUserIsSingleOwner(session.user.id);
  const user = await getUser(session.user.id);
  if (!user) {
    throw new AuthenticationError(t("common.not_authenticated"));
  }

  // Two-factor upgrade points at the user's organization billing page (org-scoped after the refactor).
  const layoutData = await getSettingsLayoutData(session.user.id);
  const billingUpgradeHref = layoutData
    ? getOrganizationBillingPath(layoutData.organization.id, IS_FORMBRICKS_CLOUD)
    : "/";

  const canUseTwoFactorAuth = isTwoFactorAuthEnabled || user.twoFactorEnabled;
  // Self-hosted without any license key: 2FA is part of the free Lite license, so offer that instead
  // of the paid upgrade.
  const showTwoFactorLiteLicenseTip =
    !canUseTwoFactorAuth && !IS_FORMBRICKS_CLOUD && (await getEnterpriseLicense()).status === "no-license";

  let securityContent: React.ReactNode;
  if (canUseTwoFactorAuth) {
    securityContent = <AccountSecurity user={user} />;
  } else if (showTwoFactorLiteLicenseTip) {
    securityContent = (
      <LiteLicenseTip
        feature="two_factor_auth"
        title={t("workspace.settings.profile.two_factor_authentication_lite_license_title")}
        description={t("common.lite_license_tip_description")}
      />
    );
  } else {
    securityContent = (
      <UpgradePrompt
        title={t("workspace.settings.profile.unlock_two_factor_authentication")}
        description={t("workspace.settings.profile.two_factor_authentication_description")}
        buttons={[
          {
            text: IS_FORMBRICKS_CLOUD ? t("common.upgrade_plan") : t("common.request_trial_license"),
            href: IS_FORMBRICKS_CLOUD ? billingUpgradeHref : ENTERPRISE_LICENSE_REQUEST_FORM_URL,
          },
          {
            text: t("common.learn_more"),
            href: IS_FORMBRICKS_CLOUD
              ? billingUpgradeHref
              : "https://formbricks.com/learn-more-self-hosting-license?utm_source=formbricks-app&utm_medium=webapp&utm_campaign=ee_lock_two_factor",
          },
        ]}
      />
    );
  }

  const isPasswordResetEnabled = !PASSWORD_RESET_DISABLED && user.identityProvider === "email";
  const requiresPasswordConfirmation = requiresPasswordConfirmationForAccountDeletion(user);

  return (
    <PageContentWrapper>
      <PageHeader pageTitle={t("common.profile")} />
      <div>
        <SettingsCard
          title={t("workspace.settings.profile.personal_information")}
          description={t("workspace.settings.profile.update_personal_info")}>
          <EditProfileDetailsForm
            user={user}
            emailVerificationDisabled={EMAIL_VERIFICATION_DISABLED}
            isPasswordResetEnabled={isPasswordResetEnabled}
          />
        </SettingsCard>
        <SettingsCard
          title={t("workspace.settings.profile.account_activity")}
          description={t("workspace.settings.profile.account_activity_description")}>
          <AccountActivity user={user} />
        </SettingsCard>
        {user.identityProvider === "email" && (
          <SettingsCard
            title={t("common.security")}
            description={t("workspace.settings.profile.security_description")}
            bodyVariant={showTwoFactorLiteLicenseTip ? "bleed" : "padded"}>
            {securityContent}
          </SettingsCard>
        )}

        <SettingsCard
          title={t("workspace.settings.profile.delete_account")}
          description={t("workspace.settings.profile.confirm_delete_account")}>
          <DeleteAccount
            session={session}
            IS_FORMBRICKS_CLOUD={IS_FORMBRICKS_CLOUD}
            user={user}
            organizationsWithSingleOwner={organizationsWithSingleOwner}
            isMultiOrgEnabled={isMultiOrgEnabled}
            requiresPasswordConfirmation={requiresPasswordConfirmation}
          />
        </SettingsCard>
        <div className="my-4 flex max-w-4xl items-center gap-4">
          <div>
            <h4 className="font-medium tracking-normal">{t("workspace.settings.profile.your_data")}</h4>
            <p className="ml-2 text-sm text-slate-500">
              {t("workspace.settings.profile.download_my_data_description")}
            </p>
          </div>
          <DownloadMyData userId={user.id} />
        </div>
        <IdBadge id={user.id} label={t("common.profile_id")} variant="column" />
      </div>
    </PageContentWrapper>
  );
};

export default Page;

import { headers } from "next/headers";
import { prisma } from "@formbricks/database";
import { getSessionUser } from "@/app/api/v1/management/me/lib/utils";
import { responses } from "@/app/lib/api/response";
import { CONTROL_HASH } from "@/lib/constants";
import { hashSha256, parseApiKeyV2, verifySecret } from "@/lib/crypto";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";

const ALLOWED_PERMISSIONS = ["manage", "read", "write"] as const;

const apiKeySelect = {
  id: true,
  organizationId: true,
  lastUsedAt: true,
  apiKeyWorkspaces: {
    select: {
      workspace: {
        select: {
          id: true,
          organizationId: true,
          legacyEnvironmentId: true,
          createdAt: true,
          updatedAt: true,
          name: true,
          appSetupCompleted: true,
        },
      },
      permission: true,
    },
  },
  hashedKey: true,
};

type ApiKeyData = {
  id: string;
  hashedKey: string;
  organizationId: string;
  lastUsedAt: Date | null;
  apiKeyWorkspaces: Array<{
    permission: string;
    workspace: {
      id: string;
      organizationId: string;
      legacyEnvironmentId: string | null;
      createdAt: Date;
      updatedAt: Date;
      name: string;
      appSetupCompleted: boolean;
    };
  }>;
};

const validateApiKey = async (apiKey: string): Promise<ApiKeyData | null> => {
  const v2Parsed = parseApiKeyV2(apiKey);

  const apiKeyData = v2Parsed ? await validateV2ApiKey(v2Parsed) : await validateLegacyApiKey(apiKey);
  if (!apiKeyData) {
    return null;
  }

  // ENG-1749: drop workspace permissions outside the key's organization (defense-in-depth,
  // mirroring authenticateApiKeyFromHeaders) so a pre-fix cross-org row can't leak workspace
  // metadata through this legacy route.
  return {
    ...apiKeyData,
    apiKeyWorkspaces: apiKeyData.apiKeyWorkspaces.filter(
      (workspacePermission) => workspacePermission.workspace.organizationId === apiKeyData.organizationId
    ),
  };
};

const validateV2ApiKey = async (v2Parsed: { secret: string }): Promise<ApiKeyData | null> => {
  // Step 1: Fast SHA-256 lookup by indexed lookupHash
  const lookupHash = hashSha256(v2Parsed.secret);

  const apiKeyData = await prisma.apiKey.findUnique({
    where: { lookupHash },
    select: apiKeySelect,
  });

  // Step 2: Security verification with bcrypt
  // Always perform bcrypt verification to prevent timing attacks
  // Use a control hash when API key doesn't exist to maintain constant timing
  const hashToVerify = apiKeyData?.hashedKey || CONTROL_HASH;
  const isValid = await verifySecret(v2Parsed.secret, hashToVerify);

  if (!apiKeyData || !isValid) return null;

  return apiKeyData;
};

const validateLegacyApiKey = async (apiKey: string): Promise<ApiKeyData | null> => {
  const hashedKey = hashSha256(apiKey);
  const result = await prisma.apiKey.findFirst({
    where: { hashedKey },
    select: apiKeySelect,
  });
  return result;
};

const checkRateLimit = async (userId: string) => {
  try {
    await applyRateLimit(rateLimitConfigs.api.v1, userId);
  } catch (error) {
    return responses.tooManyRequestsResponse(
      error instanceof Error ? error.message : "Unknown error occurred"
    );
  }
  return null;
};

const updateApiKeyUsage = async (apiKeyId: string) => {
  await prisma.apiKey.update({
    where: { id: apiKeyId },
    data: { lastUsedAt: new Date() },
  });
};

const buildWorkspaceResponse = (apiKeyData: ApiKeyData) => {
  const workspace = apiKeyData.apiKeyWorkspaces[0].workspace;
  return Response.json({
    // Keep v1 payload shape stable while sourcing data from workspace.
    id: workspace.legacyEnvironmentId ?? workspace.id,
    type: "production",
    createdAt: workspace.createdAt,
    updatedAt: workspace.updatedAt,
    appSetupCompleted: workspace.appSetupCompleted,
    workspace: {
      id: workspace.id,
      name: workspace.name,
    },
    // Backwards compat: old consumers expect project fields
    project: {
      id: workspace.id,
      name: workspace.name,
    },
  });
};

const isValidApiKeyEnvironment = (apiKeyData: ApiKeyData): boolean => {
  return (
    apiKeyData.apiKeyWorkspaces.length === 1 &&
    ALLOWED_PERMISSIONS.includes(
      apiKeyData.apiKeyWorkspaces[0].permission as (typeof ALLOWED_PERMISSIONS)[number]
    )
  );
};

const handleApiKeyAuthentication = async (apiKey: string) => {
  const apiKeyData = await validateApiKey(apiKey);

  if (!apiKeyData) {
    return responses.notAuthenticatedResponse();
  }

  if (!apiKeyData.lastUsedAt || apiKeyData.lastUsedAt <= new Date(Date.now() - 1000 * 30)) {
    // Fire-and-forget: update lastUsedAt in the background without blocking the response
    updateApiKeyUsage(apiKeyData.id).catch((error) => {
      console.error("Failed to update API key usage:", error);
    });
  }

  // Rate limiting for apiKey auth is enforced by Envoy in v5 — see envoy-rate-limit-coverage.ts
  if (!isValidApiKeyEnvironment(apiKeyData)) {
    // This legacy endpoint returns a single workspace's (environment's) details, so it only works
    // for keys scoped to exactly one workspace. Organization-only keys (no workspace) and keys with
    // multiple workspaces land here — point them at the v2 endpoint that returns full permissions.
    return responses.badRequestResponse(
      "This endpoint only supports API keys that are scoped to a single workspace. Use GET /api/v2/me to inspect organization-level API keys or keys with access to multiple workspaces."
    );
  }

  return buildWorkspaceResponse(apiKeyData);
};

const handleSessionAuthentication = async () => {
  const sessionUser = await getSessionUser();

  if (!sessionUser) {
    return responses.notAuthenticatedResponse();
  }

  const rateLimitError = await checkRateLimit(sessionUser.id);
  if (rateLimitError) return rateLimitError;

  const user = await prisma.user.findUnique({
    where: { id: sessionUser.id },
    select: {
      id: true,
      name: true,
      email: true,
      emailVerified: true,
      createdAt: true,
      updatedAt: true,
      twoFactorEnabled: true,
      identityProvider: true,
      notificationSettings: true,
      locale: true,
      lastLoginAt: true,
      isActive: true,
    },
  });

  return Response.json(user);
};

export const GET = async () => {
  const headersList = await headers();
  const apiKey = headersList.get("x-api-key");

  if (apiKey) {
    return handleApiKeyAuthentication(apiKey);
  }

  return handleSessionAuthentication();
};

import { NextApiResponse } from "next";

export type ApiResponse = ApiSuccessResponse | ApiErrorResponse;

interface ApiSuccessResponse<T = { [key: string]: unknown }> {
  data: T;
}

interface ApiErrorResponse {
  code:
    | "not_found"
    | "gone"
    | "bad_request"
    | "internal_server_error"
    | "unauthorized"
    | "method_not_allowed"
    | "not_authenticated"
    | "forbidden"
    | "too_many_requests"
    | "conflict"
    | "payload_too_large"
    | "service_unavailable"
    | "workspace_survey_limit_reached";
  message: string;
  details: {
    [key: string]: string | string[] | number | number[] | boolean | boolean[];
  };
}

export type CustomNextApiResponse = NextApiResponse<ApiResponse>;

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization",
};

const goneResponse = (
  message: string,
  details?: { [key: string]: string },
  cors: boolean = false,
  cache: string = "private, no-store"
) => {
  const headers = {
    ...(cors && corsHeaders),
    "Cache-Control": cache,
  };

  return Response.json(
    {
      code: "gone",
      message,
      details: details || {},
    } as ApiErrorResponse,
    {
      status: 410,
      headers,
    }
  );
};

